const W = 826, H = 1524;

// --- 2. КОНФИГУРАЦИЯ АНИМАЦИИ ---
const AMBIENT = {
  0: { fx:1.40, fy:1.00, ax:3,  ay:2,   phase:0.0 },
  1: { fx:0.65, fy:0.90, ax:2,  ay:1.6, phase:1.4 },
  2: { fx:0.90, fy:0.75, ax:4,  ay:2.5, phase:0.9 },
  3: { fx:0.95, fy:0.80, ax:4,  ay:2.5, phase:2.6 },
  4: { fx:0.60, fy:0.50, ax:5,  ay:3,   phase:0.4 },
  5: { fx:0.62, fy:0.53, ax:5,  ay:3,   phase:3.0 },
};

const PULL = {
  2: { freq:0.90, phase:2.1, sharp:2.0, amp:95, dx:-1.0, dy:-0.15, swingAmp:50, swingFreqMul:1.8, swingDX:0.15,  swingDY:-1.0 },
  3: { freq:1.00, phase:4.4, sharp:2.0, amp:95, dx:1.0,  dy:-0.15, swingAmp:50, swingFreqMul:1.8, swingDX:-0.15, swingDY:-1.0 },
};

const HEAD_TURN = { freq:0.80, phase:0.0, ampX:38, ampY:10, nodFreq:1.1, nodPhase:1.2, sharp:1.6 };
const TENSION_THRESHOLD = 0.58;

const ARM_ANCHOR = { 2: { x: 311.7, y: 392.6 }, 3: { x: 566.9, y: 391.4 } };

const reach = {
  2: { amt: 0, goal: 0, tx: ARM_ANCHOR[2].x, ty: ARM_ANCHOR[2].y },
  3: { amt: 0, goal: 0, tx: ARM_ANCHOR[3].x, ty: ARM_ANCHOR[3].y },
};

const REACH_SMOOTH = 0.08;
const PARTICLES_PER_LINE = 2;
const PARTICLE_SPEED = 0.6;
const SCAN = { period: 9.0, bandHalf: 130 };
const SPEED = 1.0;

// --- 3. ГЛАВНАЯ ФУНКЦИЯ ---
export function initFigureAnimation() {
  const canvas = document.getElementById('c');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');

  let SCAN_Y_MIN = Infinity, SCAN_Y_MAX = -Infinity;
  for (const p of POINTS) {
    if (!p || p.length === 0) continue;
    if (p[1] < SCAN_Y_MIN) SCAN_Y_MIN = p[1]; 
    if (p[1] > SCAN_Y_MAX) SCAN_Y_MAX = p[1]; 
  }

  function scanY_at(t) {
    const span = SCAN_Y_MAX - SCAN_Y_MIN;
    const phase = (t % SCAN.period) / SCAN.period;
    const pos = phase < 0.5 ? phase * 2 : 2 - phase * 2;
    return SCAN_Y_MIN + pos * span;
  }

  function scanGlowAt(y, t) {
    const d = Math.abs(y - scanY_at(t));
    return d < SCAN.bandHalf ? (1 - d / SCAN.bandHalf) : 0;
  }

  let scale = 1, offsetX = 0, offsetY = 0;

  function resize() {
    const rect = canvas.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    canvas.width = Math.round(rect.width * dpr);
    canvas.height = Math.round(rect.height * dpr);

    // Вычисляем единый масштаб со сохранением пропорций (Contain)
    scale = Math.min(rect.width / W, rect.height / H);
    
    // Центрируем модель внутри Canvas
    offsetX = (rect.width - W * scale) / 2;
    offsetY = (rect.height - H * scale) / 2;

    ctx.setTransform(dpr * scale, 0, 0, dpr * scale, dpr * offsetX, dpr * offsetY);
  }
  
  window.addEventListener('resize', resize);
  resize();

  const buckets = new Map();
  const QC = 24, QA = 0.04;
  for (let e = 0; e < EDGES.length; e++) {
    if (!EDGES[e] || EDGES[e].length === 0) continue;
    const [i, j, tag] = EDGES[e];
    if (tag === 2) continue;
    const p1 = POINTS[i], p2 = POINTS[j];
    if (!p1 || !p2) continue;
    const lum = (p1[7] + p2[7]) / 2;
    const shadow = 1 - lum;
    let r = (p1[4] + p2[4]) / 2 * (1 - 0.45*shadow);
    let g = (p1[5] + p2[5]) / 2 * (1 - 0.45*shadow);
    let b = (p1[6] + p2[6]) / 2 * (1 - 0.45*shadow);
    let alpha;
    if (tag === 0) alpha = 0.09 + 0.50*shadow;
    else if (tag === 1) alpha = 0.04 + 0.26*shadow;
    else alpha = 0.07 + 0.34*shadow;
    const rq = Math.round(r / QC) * QC, gq = Math.round(g / QC) * QC, bq = Math.round(b / QC) * QC;
    const aq = Math.round(alpha / QA) * QA;
    const key = tag + "_" + rq + "_" + gq + "_" + bq + "_" + aq.toFixed(2);
    let bucket = buckets.get(key);
    if (!bucket) { bucket = { style: `rgba(${rq},${gq},${bq},${aq.toFixed(2)})`, tag, pairs: [] }; buckets.set(key, bucket); }
    bucket.pairs.push(i, j);
  }
  const bucketList = Array.from(buckets.values());

  const baseR = new Array(POINTS.length), baseG = new Array(POINTS.length), baseB = new Array(POINTS.length);
  const pointRadius = new Array(POINTS.length);
  for (let i = 0; i < POINTS.length; i++) {
    const p = POINTS[i];
    if (!p || p.length === 0) continue;
    const shadow = 1 - p[7];
    baseR[i] = Math.round(p[4] * (1 - 0.3*shadow));
    baseG[i] = Math.round(p[5] * (1 - 0.3*shadow));
    baseB[i] = Math.round(p[6] * (1 - 0.3*shadow));
    pointRadius[i] = 0.9 + p[3] * 1.5;
  }

  const cur = new Float32Array(POINTS.length * 2);
  const tension = new Float32Array(POINTS.length);

  const strandStart = [], strandLen = [], strandReg = [];
  let strandTotal = 0;
  for (const s of STRANDS) { 
    strandStart.push(strandTotal); 
    strandLen.push(s.pts.length); 
    strandReg.push(s.reg); 
    strandTotal += s.pts.length; 
  }
  const strandX0 = new Float32Array(strandTotal), strandY0 = new Float32Array(strandTotal), strandW = new Float32Array(strandTotal);
  const strandSeed = new Float32Array(STRANDS.length), strandFj = new Float32Array(STRANDS.length);
  
  let k = 0;
  for (let s = 0; s < STRANDS.length; s++) {
    strandSeed[s] = (((s * 0.6180339887) % 1) * 2) - 1;
    strandFj[s] = 1 + strandSeed[s] * 0.12;
    for (const [x0, y0, w] of STRANDS[s].pts) { strandX0[k] = x0; strandY0[k] = y0; strandW[k] = w; k++; }
  }
  
  const strandCurX = new Float32Array(strandTotal), strandCurY = new Float32Array(strandTotal), strandTension = new Float32Array(strandTotal);

  function regionDisplacement(reg, w, seed, fj, t) {
    const am = AMBIENT[reg] || AMBIENT[0];
    const ph = am.phase + seed;
    let dx = w * am.ax * Math.sin(t * am.fx * fj + ph);
    let dy = w * am.ay * Math.cos(t * am.fy * fj + ph * 1.3);
    let tens = 0;
    const pull = PULL[reg];
    if (pull) {
      const raw = 0.5 - 0.5*Math.cos(t * pull.freq * fj + pull.phase + seed*0.3);
      const env = Math.pow(Math.max(raw,0), pull.sharp);
      tens = env;
      const stretch = env * pull.amp * w;
      dx += stretch * pull.dx;
      dy += stretch * pull.dy;
      const swing = Math.sin(t * pull.freq * fj * pull.swingFreqMul + pull.phase * 1.3 + seed*0.4) * pull.swingAmp * w;
      dx += swing * pull.swingDX;
      dy += swing * pull.swingDY;
    } else if (reg === 0) {
      const turn = Math.sin(t * HEAD_TURN.freq * fj + HEAD_TURN.phase + seed*0.3);
      const nod = Math.sin(t * HEAD_TURN.nodFreq * fj + HEAD_TURN.nodPhase + seed*0.3);
      dx += w * HEAD_TURN.ampX * turn;
      dy += w * HEAD_TURN.ampY * nod;
      tens = Math.pow(Math.abs(turn), HEAD_TURN.sharp);
    }
    return [dx, dy, tens];
  }

  function updateReach() {
    for (const reg of [2, 3]) {
      const r = reach[reg];
      r.amt += (r.goal - r.amt) * REACH_SMOOTH;
      if (Math.abs(r.amt - r.goal) < 0.001) r.amt = r.goal;
    }
  }

  function updateStrands(t) {
    for (let s = 0; s < STRANDS.length; s++) {
      const reg = strandReg[s], seed = strandSeed[s], fj = strandFj[s];
      const start = strandStart[s], len = strandLen[s];
      for (let k = 0; k < len; k++) {
        const idx = start + k;
        const w = strandW[idx];
        const [dx, dy, tens] = regionDisplacement(reg, w, seed, fj, t);
        const x = strandX0[idx] + dx, y = strandY0[idx] + dy;
        strandCurX[idx] = x; strandCurY[idx] = y;
        const scanG = scanGlowAt(y, t);
        strandTension[idx] = Math.max(tens * w, scanG);
      }
    }
  }

  function update(t) {
    for (let i = 0; i < POINTS.length; i++) {
      const p = POINTS[i];
      if (!p || p.length === 0) continue;
      const reg = p[2], w = p[3], seed = p[8], fj = p[9];
      const [dx, dy, tens] = regionDisplacement(reg, w, seed, fj, t);
      cur[i*2] = p[0] + dx;
      cur[i*2+1] = p[1] + dy;
      const scanG = scanGlowAt(cur[i*2+1], t);
      tension[i] = Math.max(tens * w, scanG);
    }
  }

const mouse = { x: -99999, y: -99999 };
const diagramWrap = document.getElementById('diagramWrap') || window;

diagramWrap.addEventListener('mousemove', (e) => {
  const rect = (document.getElementById('diagramWrap') || canvas).getBoundingClientRect();
  
  // Перевод координат мыши в локальные координаты модели 826x1524
  mouse.x = (e.clientX - rect.left - offsetX) / scale;
  mouse.y = (e.clientY - rect.top - offsetY) / scale;
});

diagramWrap.addEventListener('mouseleave', () => { 
  mouse.x = -99999; 
  mouse.y = -99999; 
});
  canvas.addEventListener('mouseleave', () => { mouse.x = -99999; mouse.y = -99999; });

  const CURSOR_R = 150;      
  const CURSOR_REPEL = 24;   
  const CURSOR_KNOT = 0.60;  

  function applyCursorField() {
    if (mouse.x < -50000) return;
    const R2 = CURSOR_R * CURSOR_R;

    let nearestIdx = -1, nearestD2 = Infinity;
    for (let i = 0; i < POINTS.length; i++) {
      if (!POINTS[i] || POINTS[i].length === 0) continue;
      const dx = cur[i*2] - mouse.x, dy = cur[i*2+1] - mouse.y;
      const d2 = dx*dx + dy*dy;
      if (d2 < R2 && d2 < nearestD2) { nearestD2 = d2; nearestIdx = i; }
    }
    if (nearestIdx < 0) return;
    const ax = cur[nearestIdx*2], ay = cur[nearestIdx*2+1];

    for (let i = 0; i < POINTS.length; i++) {
      if (!POINTS[i] || POINTS[i].length === 0) continue;
      const px = cur[i*2], py = cur[i*2+1];
      const dxm = px - mouse.x, dym = py - mouse.y;
      const d = Math.sqrt(dxm*dxm + dym*dym);
      if (d >= CURSOR_R) continue;
      const infl = 1 - d / CURSOR_R, infl2 = infl * infl;
      const nx = d > 0.001 ? dxm / d : 0, ny = d > 0.001 ? dym / d : 0;
      let ex = nx * infl2 * CURSOR_REPEL, ey = ny * infl2 * CURSOR_REPEL;
      if (i !== nearestIdx) {
        ex += (ax - px) * infl2 * CURSOR_KNOT;
        ey += (ay - py) * infl2 * CURSOR_KNOT;
      }
      cur[i*2] = px + ex;
      cur[i*2+1] = py + ey;
    }

    for (let k = 0; k < strandTotal; k++) {
      const px = strandCurX[k], py = strandCurY[k];
      const dxm = px - mouse.x, dym = py - mouse.y;
      const d = Math.sqrt(dxm*dxm + dym*dym);
      if (d >= CURSOR_R) continue;
      const infl = 1 - d / CURSOR_R, infl2 = infl * infl;
      const nx = d > 0.001 ? dxm / d : 0, ny = d > 0.001 ? dym / d : 0;
      const ex = nx * infl2 * CURSOR_REPEL * 0.7 + (ax - px) * infl2 * CURSOR_KNOT * 0.8;
      const ey = ny * infl2 * CURSOR_REPEL * 0.7 + (ay - py) * infl2 * CURSOR_KNOT * 0.8;
      strandCurX[k] = px + ex;
      strandCurY[k] = py + ey;
    }
  }

  function draw(t, realT) {
    // Очищаем canvas прозрачным фоном, чтобы не перекрывать верстку
    ctx.clearRect(0, 0, W, H);

    ctx.lineWidth = 0.7;
    for (const bucket of bucketList) {
      ctx.strokeStyle = bucket.style;
      ctx.beginPath();
      const pairs = bucket.pairs;
      for (let k = 0; k < pairs.length; k += 2) {
        const i = pairs[k], j = pairs[k+1];
        ctx.moveTo(cur[i*2], cur[i*2+1]);
        ctx.lineTo(cur[j*2], cur[j*2+1]);
      }
      ctx.stroke();
    }

    ctx.strokeStyle = "rgba(150,140,130,0.42)";
    ctx.lineWidth = 1.0;
    ctx.beginPath();
    for (let s = 0; s < STRANDS.length; s++) {
      const start = strandStart[s], len = strandLen[s];
      ctx.moveTo(strandCurX[start], strandCurY[start]);
      for (let k = 1; k < len; k++) ctx.lineTo(strandCurX[start+k], strandCurY[start+k]);
    }
    ctx.stroke();

    for (let s = 0; s < STRANDS.length; s++) {
      const start = strandStart[s], len = strandLen[s];
      for (let k = 0; k < len; k++) {
        const idx = start + k;
        const tens = strandTension[idx];
        if (tens <= TENSION_THRESHOLD) continue;
        const glow = (tens - TENSION_THRESHOLD) / (1 - TENSION_THRESHOLD);
        ctx.strokeStyle = `rgba(255,255,255,${(0.8*glow).toFixed(3)})`;
        ctx.lineWidth = 1.1 + 2.2*glow;
        ctx.beginPath();
        if (k > 0) { ctx.moveTo(strandCurX[idx-1], strandCurY[idx-1]); ctx.lineTo(strandCurX[idx], strandCurY[idx]); }
        if (k < len-1) { ctx.moveTo(strandCurX[idx], strandCurY[idx]); ctx.lineTo(strandCurX[idx+1], strandCurY[idx+1]); }
        ctx.stroke();
      }
    }

    ctx.shadowColor = "rgba(255,255,255,0.95)";
    for (let i = 0; i < POINTS.length; i++) {
      if (!POINTS[i] || POINTS[i].length === 0) continue;
      const tens = tension[i];
      const glow = tens > TENSION_THRESHOLD ? (tens - TENSION_THRESHOLD) / (1 - TENSION_THRESHOLD) : 0;
      if (glow > 0) {
        const r = Math.round(baseR[i] + (255 - baseR[i]) * glow);
        const g = Math.round(baseG[i] + (255 - baseG[i]) * glow);
        const b = Math.round(baseB[i] + (255 - baseB[i]) * glow);
        ctx.fillStyle = `rgb(${r},${g},${b})`;
        ctx.shadowBlur = 9 * glow;
        ctx.beginPath();
        ctx.arc(cur[i*2], cur[i*2+1], pointRadius[i] * (1 + 1.4*glow), 0, Math.PI * 2);
        ctx.fill();
      } else {
        ctx.shadowBlur = 0;
        ctx.fillStyle = `rgb(${baseR[i]},${baseG[i]},${baseB[i]})`;
        ctx.beginPath();
        ctx.arc(cur[i*2], cur[i*2+1], pointRadius[i], 0, Math.PI * 2);
        ctx.fill();
      }
    }
    ctx.shadowBlur = 0;

    for (let i = 0; i < POINTS.length; i++) {
      if (!POINTS[i] || POINTS[i].length === 0 || !ADJ[i]) continue;
      const tens = tension[i];
      if (tens <= TENSION_THRESHOLD) continue;
      const glow = (tens - TENSION_THRESHOLD) / (1 - TENSION_THRESHOLD);
      const neighbors = ADJ[i];
      ctx.strokeStyle = `rgba(255,255,255,${(0.55*glow).toFixed(3)})`;
      ctx.lineWidth = 0.6 + 1.4*glow;
      ctx.beginPath();
      for (let k = 0; k < neighbors.length; k++) {
        const j = neighbors[k];
        ctx.moveTo(cur[i*2], cur[i*2+1]);
        ctx.lineTo(cur[j*2], cur[j*2+1]);
      }
      ctx.stroke();
    }

    const scanY = scanY_at(t);
    const WAVE_TOL = 14;   
    const WAVE_BIN = 14;   
    for (let reg = 0; reg <= 5; reg++) {
      const bins = new Map(); 
      for (let i = 0; i < POINTS.length; i++) {
        if (!POINTS[i] || POINTS[i].length === 0 || POINTS[i][2] !== reg) continue;
        const y = cur[i*2+1];
        const dd = Math.abs(y - scanY);
        if (dd >= WAVE_TOL) continue;
        const x = cur[i*2];
        const key = Math.round(x / WAVE_BIN);
        const cur_best = bins.get(key);
        if (!cur_best || dd < cur_best[2]) bins.set(key, [x, y, dd]);
      }
      if (bins.size < 2) continue;
      const grp = Array.from(bins.values()).map(([x,y,dd]) => [x, y, 1 - dd/WAVE_TOL]);
      grp.sort((a, b) => a[0] - b[0]);
      let maxA = 0;
      for (const p of grp) if (p[2] > maxA) maxA = p[2];

      ctx.strokeStyle = `rgba(255,255,255,${(0.9*maxA).toFixed(3)})`;
      ctx.lineWidth = 1.7;
      ctx.beginPath();
      ctx.moveTo(grp[0][0], grp[0][1] - 3);
      for (let k = 1; k < grp.length; k++) {
        const x1 = grp[k-1][0], y1 = grp[k-1][1] - 3, x2 = grp[k][0], y2 = grp[k][1] - 3;
        ctx.quadraticCurveTo((x1+x2)/2, (y1+y2)/2 + 6, x2, y2);
      }
      ctx.stroke();

      ctx.strokeStyle = `rgba(185,192,205,${(0.6*maxA).toFixed(3)})`;
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(grp[0][0], grp[0][1] + 4);
      for (let k = 1; k < grp.length; k++) {
        const x1 = grp[k-1][0], y1 = grp[k-1][1] + 4, x2 = grp[k][0], y2 = grp[k][1] + 4;
        ctx.quadraticCurveTo((x1+x2)/2, (y1+y2)/2 - 6, x2, y2);
      }
      ctx.stroke();
    }

    for (const reg of [2, 3]) {
      const r = reach[reg];
      if (r.amt <= 0.01) continue;
      for (let i = 0; i < POINTS.length; i++) {
        const p = POINTS[i];
        if (!p || p.length === 0 || p[2] !== reg) continue;
        const px = cur[i*2], py = cur[i*2+1];
        const shadow = 1 - p[7];
        const rr = Math.round(p[4] * (1 - 0.2*shadow));
        const gg = Math.round(p[5] * (1 - 0.2*shadow));
        const bb = Math.round(p[6] * (1 - 0.2*shadow));
        const alpha = 0.10 * r.amt * (0.4 + 0.6*p[3]);
        const grad = ctx.createLinearGradient(px, py, r.tx, r.ty);
        grad.addColorStop(0, `rgba(${rr},${gg},${bb},${alpha.toFixed(3)})`);
        grad.addColorStop(1, `rgba(${rr},${gg},${bb},0)`);
        ctx.strokeStyle = grad;
        ctx.lineWidth = 0.7;
        ctx.beginPath();
        ctx.moveTo(px, py);
        ctx.lineTo(r.tx, r.ty);
        ctx.stroke();

        for (let pIdx = 0; pIdx < PARTICLES_PER_LINE; pIdx++) {
          const phase = (realT * PARTICLE_SPEED + i * 0.013 + pIdx / PARTICLES_PER_LINE) % 1;
          const fade = Math.sin(phase * Math.PI);
          const qx = px + (r.tx - px) * phase;
          const qy = py + (r.ty - py) * phase;
          ctx.fillStyle = `rgba(${rr},${gg},${bb},${(alpha * 5 * fade).toFixed(3)})`;
          ctx.beginPath();
          ctx.arc(qx, qy, 1.3, 0, Math.PI * 2);
          ctx.fill();
        }
      }
    }
  }

let bodyT = 0;
  let lastRealT = null;
  let lastMouseUpdate = 0;
  let isAnimating = false;
  let animFrameId = null;

  function loop(now) {
    if (!isAnimating) return; // Полная остановка цикла, когда слайд скрыт

    const realT = (now / 1000) * SPEED;
    if (lastRealT === null) lastRealT = realT;
    const dt = Math.min(realT - lastRealT, 0.1); 
    lastRealT = realT;

    updateReach();
    const hoverActive = Math.max(reach[2].amt, reach[3].amt);
    bodyT += dt * (1 - hoverActive);

    update(bodyT);
    updateStrands(bodyT);

    if (now - lastMouseUpdate > 15) {
      applyCursorField();
      lastMouseUpdate = now;
    }

    draw(bodyT, realT);
    animFrameId = requestAnimationFrame(loop);
  }
  
  // Запускаем и останавливаем Canvas при прокрутке
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        if (!isAnimating) {
          isAnimating = true;
          lastRealT = null;
          animFrameId = requestAnimationFrame(loop);
        }
      } else {
        isAnimating = false;
        if (animFrameId) cancelAnimationFrame(animFrameId);
      }
    });
  }, { threshold: 0.01 });
  
  const favSection = document.getElementById('favorites');
  if (favSection) observer.observe(favSection);

  // Привязка hover-эффектов к элементам карточек проектов
  document.querySelectorAll('.fav-item').forEach((item) => {
    const side = item.dataset.side === '-1' ? 2 : 3;
    const rowPct = parseFloat(item.dataset.row || '0.5');
    const targetX = (side === 2 ? 0.06 : 0.94) * W;
    const targetY = rowPct * H;

    item.addEventListener('mouseenter', () => {
      const r = reach[side];
      r.tx = targetX; 
      r.ty = targetY; 
      r.goal = 1;
    });
    item.addEventListener('mouseleave', () => {
      reach[side].goal = 0;
    });
  });
} // Закрывающая скобка initFigureAnimation()

// Автоматический запуск анимации после загрузки DOM
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initFigureAnimation);
} else {
  initFigureAnimation();
}